    /** Repository owner */
    owner: string;
    repo: string;
    /** *\/ not a comment end */
    state?: "open" | "closed" | "all";
    per_page?: number;
    labels?: string[];
    /** @format date-time */
    since?: string;
    /** Quoted name */
    "x-trace-id"?: string;
    filter?: {
        author: string;
        draft?: boolean;
    };
    sort?: string | null;
    page?: number | string;
    meta?: {
        [key: string]: string;
    };
    extra?: {
        [key: string]: unknown;
    };
    none?: {};
    kind?: "pr";
    pair?: [string, number];
    tuple?: [boolean];
    any?: unknown;
    nullable?: string | null;
    multi?: string | null | unknown[];
    ref?: {
        name?: string;
    };
    both?: {
        a?: string;
    } & {
        b?: number;
    };
    mixed?: 1 | "two" | null | true | {"x":1};
    never: never;
    always?: unknown;
    "1st"?: number;
}
type ListPullRequestsOutput = {
    items?: {
        number: number;
        title?: string;
    }[];
}
type Delete_Input = {
    id?: number;
}
